#!/usr/bin/env node
/**
 * Gate: documentation facts must match the generated manifest.
 *
 * Docs hand-write counts like "156 components × 4 = 624 native contracts".
 * Those drifted before (151 / 155 / 156 all appear in history) because
 * nothing compared them against the source of truth. This script is the
 * reconciliation: read `packages/manifest/manifest.json` (generated by
 * `pnpm gen:manifest`) and assert every declared count still holds.
 *
 * Only *current-state* declaration docs are checked. Historical records
 * (docs/vxe-grid/*, docs/ui-audit/*, dated SPRINT/CHANGELOG entries) are
 * snapshots of what was true at the time and are deliberately not enforced.
 *
 * Usage: node scripts/check-doc-facts.mjs [--write]
 *   --write  rewrite the `> 事实来源` line in the baseline header instead of
 *            failing, so `pnpm gen:manifest` can be followed by a single
 *            `check:doc-facts --write` to resync.
 */
import { existsSync, readFileSync, writeFileSync } from 'node:fs'
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..')
const manifestPath = resolve(root, 'packages/manifest/manifest.json')

if (!existsSync(manifestPath)) {
  process.stderr.write(
    'check:doc-facts: packages/manifest/manifest.json not found — run `pnpm gen:manifest` first.\n',
  )
  process.exit(1)
}

const manifest = JSON.parse(readFileSync(manifestPath, 'utf8'))
const total = manifest.stats.total
const frameworks = Object.keys(manifest.stats.byFramework)
const contracts = frameworks.length * total
const tokens = manifest.tokens.all.length

// Recompute from the component list rather than trusting `stats`.
const groupCounts = {}
let nativeContracts = 0
let unavailable = 0
for (const component of manifest.components) {
  groupCounts[component.group] = (groupCounts[component.group] ?? 0) + 1
  for (const contract of Object.values(component.frameworkContracts ?? {})) {
    if (contract.source === 'native') nativeContracts += 1
    else unavailable += 1
  }
}
if (nativeContracts !== contracts || unavailable !== 0) {
  process.stderr.write(
    `check:doc-facts: manifest is self-inconsistent: ${total} components × ${frameworks.length} frameworks = ${contracts}, ` +
      `but ${nativeContracts} native + ${unavailable} unavailable contracts.\n`,
  )
  process.exit(1)
}

const facts = {
  total,
  contracts: nativeContracts,
  tokens,
  frameworks: frameworks.join('/'),
  groups: groupCounts,
}

const write = process.argv.includes('--write')
const failures = []
const ok = []

/** Assert a file contains `needle`, reporting the file when it does not. */
function expect(file, needle, label) {
  const path = resolve(root, file)
  if (!existsSync(path)) {
    failures.push(`${file}: missing (${label})`)
    return
  }
  if (readFileSync(path, 'utf8').includes(needle)) ok.push(`${file} — ${label}`)
  else failures.push(`${file}: expected to declare "${needle}" (${label})`)
}

const groupRows = Object.entries(groupCounts)
  .map(([group, count]) => ({ group, count }))
  .sort((a, b) => b.count - a.count)

for (const file of [
  'README.md',
  'AGENTS.md',
  'docs/ARCHITECTURE.md',
  'docs/AUTONOMOUS.md',
  'docs/STATE.md',
  'docs/TODO.md',
  'docs/ROADMAP.md',
  'docs/requirements/REQUIREMENTS-BASELINE.md',
]) {
  expect(file, String(total), 'component count')
  expect(file, String(contracts), 'native contract count')
}

expect('README.md', `${total} components in each of four frameworks`, 'per-adapter count')
expect('AGENTS.md', `${total} 组件 × 4 = ${contracts} 份契约`, 'contract arithmetic')
expect('docs/ARCHITECTURE.md', `${total} × 4 = ${contracts}`, 'contract arithmetic')
expect('docs/STATE.md', `记录 ${total} 个组件`, 'per-framework parity')
expect(
  'docs/requirements/REQUIREMENTS-BASELINE.md',
  `## 2. 组件面需求（${total} × 4）`,
  'baseline heading',
)

// Group table in the requirements baseline must match the manifest breakdown.
const baselinePath = resolve(root, 'docs/requirements/REQUIREMENTS-BASELINE.md')
if (existsSync(baselinePath)) {
  let baseline = readFileSync(baselinePath, 'utf8')
  for (const { group, count } of groupRows) {
    const row = new RegExp(`^\\|\\s*${group}\\s*\\|\\s*\\*?\\*?${count}\\b`, 'm')
    if (row.test(baseline)) ok.push(`baseline group row — ${group}=${count}`)
    else
      failures.push(
        `docs/requirements/REQUIREMENTS-BASELINE.md: group row "${group}" should be ${count}`,
      )
  }

  // The source-of-truth line in the header is machine-rewritable.
  const generatedHeader = `> 生成日期：${new Date().toISOString().slice(0, 10)} · 来源：\`packages/manifest/manifest.json\`（${total} 组件 × ${frameworks.length} 框架，`
  // Keep the `> ` blockquote marker: the counts sit on the header's second
  // line, and dropping the marker silently breaks the blockquote (and the
  // rewrite pattern that finds it again).
  const generatedHeaderTail = `> ${contracts} 份 native contract / 0 unavailable，${tokens} token）+ 仓库文档。`
  if (write) {
    // The counts live on a blockquote continuation line, i.e. the line starts
    // with `>`, not with a digit. The old `^\d+ 份 native contract` pattern
    // therefore never matched, so `--write` rewrote only the date, reported
    // "rewritten from manifest", and the very next check still failed. Match the
    // line as written, and fail closed when it is not found at all.
    const rewritten = baseline
      .replace(/^> 生成日期：.*$/m, generatedHeader)
      .replace(/^>.*\d+ 份 native contract.*$/m, generatedHeaderTail)
    if (rewritten === baseline && !baseline.includes(generatedHeaderTail)) {
      failures.push(
        'docs/requirements/REQUIREMENTS-BASELINE.md: could not find the machine-rewritable ' +
          '"N 份 native contract" header line to update (its format changed?)',
      )
    } else {
      writeFileSync(baselinePath, rewritten)
      ok.push('baseline header — rewritten from manifest')
    }
  } else if (
    !baseline.includes(`${total} 组件 × ${frameworks.length} 框架`) ||
    !baseline.includes(generatedHeaderTail)
  ) {
    failures.push(
      'docs/requirements/REQUIREMENTS-BASELINE.md: header source-of-truth line is stale (run `pnpm check:doc-facts --write`)',
    )
  }
}

if (failures.length > 0) {
  process.stderr.write(`\ncheck:doc-facts: ${failures.length} stale declaration(s)\n`)
  for (const failure of failures) process.stderr.write(`  ✗ ${failure}\n`)
  process.stderr.write(
    `\nRegenerate with: pnpm gen:manifest && pnpm check:doc-facts --write\n` +
      `Ground truth: ${total} components × ${frameworks.length} = ${contracts} native contracts, ${tokens} tokens\n`,
  )
  process.exit(1)
}

process.stdout.write(
  `check:doc-facts: ${ok.length} declaration(s) match manifest ` +
    `(${total} components × ${frameworks.length} = ${contracts} native contracts, ${tokens} tokens)\n`,
)
